#!/usr/bin/env bash
set -euo pipefail

# Generate .github/workflows/build.yml from the package sources.
#
# GitHub Actions cannot derive job structure at run time, so the per-node build
# pipeline is generated offline and committed. The pipeline is
#
#   pkgs/ --(glbx graph)--> graph JSON --(jq)--> build.yml
#
# run end to end here: glbx reads the sources and emits the deterministic graph,
# jq turns it into one job per node. Nothing in between is stored — build.yml is
# the only committed derived artefact, and the check-graph CI job regenerates it
# from the current sources and fails the run if it has drifted.
#
# The pipeline builds every architecture in ARCHES. glbx is pure Go, so a single
# build-glbx job cross-compiles all arches (one glbx-bin-<arch> artifact each);
# but a node's actual build runs native code in the sandbox, so each arch gets
# its own restore-inputs/plan preamble and its own copy of every node job,
# pinned to a runner of that architecture. Graph node Keys already embed the
# arch (e.g. debian-pkg-build:bash:arm64), so the two arches' node sets are
# disjoint and never collide.
#
# The generated file is thin: all build logic lives in hand-authored reusable
# workflows (.github/workflows/{build-glbx,check-graph,restore-inputs,plan,
# build-node}.yml). Only the graph-shaped wiring is generated — one caller job
# per (node, arch) that `uses:` build-node.yml, carrying the node's needs: edges
# and the already-built skip guard, which are structural and so must stay in the
# committed file for check-graph to validate.
#
# One graph node becomes one caller job of build-node.yml, which internally runs
# two jobs: `build` builds exactly that node with recursion inhibited (every
# dependency must already be a cache hit from an earlier node's publish) and
# publishes it to ghcr, then `check-reprod` re-verifies the node reproduces that
# output. Graph edges become the caller job's needs:; when the node is an
# already-built cache hit the caller job skips, so both inner jobs skip and
# reproducibility is re-checked only for nodes actually rebuilt.
#
# Usage: .github/generate-workflow.sh [output-yml]
#   output-yml  default .github/workflows/build.yml
# Environment:
#   GLBX    path to the glbx binary          (default: glbx on PATH)
#   STUB    path to the exec_env_stub binary (default: exec_env_stub on PATH)
#   ARCHES  space-separated target arches    (default: "amd64 arm64")

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
CONF_DIR="$(cd "$SCRIPT_DIR/.." && pwd)"
OUT="${1:-$SCRIPT_DIR/workflows/build.yml}"

GLBX="${GLBX:-glbx}"
STUB="${STUB:-exec_env_stub}"
ARCHES="${ARCHES:-amd64 arm64}"

# Per-node runner map:
#   {"default": {<arch>: <label>}, "overrides": {<exact node Key>: <label>}}.
# Read into the jq pass below; a node with no exact-Key override gets the
# per-arch default. Overrides are keyed on the arch-qualified node Key, so they
# are already arch-specific and need no further branching.
RUNNERS="$SCRIPT_DIR/runners.json"

mkdir -p "$(dirname "$OUT")"

{
	# Static header and the arch-independent preamble jobs, each a thin caller of
	# a reusable workflow. A quoted heredoc delimiter keeps ${{ ... }} GitHub
	# expressions literal — the shell must not touch them. build-glbx builds all
	# arches in one job; check-graph only regenerates and diffs this file, so it
	# needs just one (amd64) glbx binary and is arch-independent.
	cat <<'EOF'
# Generated by .github/generate-workflow.sh from the package sources.
# Do not edit by hand: edit the sources, regenerate, and commit. The
# check-graph job fails the run if this file is stale.
name: build

on:
  workflow_dispatch:
    inputs:
      glbx-ref:
        description: glbx ref (branch, tag, or full SHA) to build the executor from
        default: main
        type: string
      id-seed-override:
        description: >-
          Override the global identity seed to force a full rebuild (leave empty
          for a normal cache-honoring build)
        default: ""
        type: string
  push:
  # A pull_request build runs against the PR's merge ref, so the gate reflects the
  # merged state rather than the branch tip. A branch pushed by the automatic
  # GITHUB_TOKEN does not trigger this (bot-opened PR events need approval), so an
  # update PR's build starts when a maintainer pushes to it or approves the run.
  pull_request:

permissions:
  contents: read
  packages: write

jobs:

  build-glbx:
    uses: ./.github/workflows/build-glbx.yml
    with:
      glbx-ref: ${{ inputs.glbx-ref || 'main' }}

  check-graph:
    needs: [build-glbx]
    uses: ./.github/workflows/check-graph.yml
EOF

	# Per-arch preamble: restore-inputs and plan, one copy per architecture.
	# Suffixed job ids keep them distinct; each node job of that arch needs: its
	# own arch's plan/restore-inputs.
	for a in $ARCHES; do
		cat <<EOF

  restore-inputs-$a:
    needs: [build-glbx]
    uses: ./.github/workflows/restore-inputs.yml
    with:
      arch: $a

  plan-$a:
    needs: [build-glbx, check-graph]
    uses: ./.github/workflows/plan.yml
    with:
      arch: $a
      id-seed-override: \${{ inputs.id-seed-override }}
EOF
	done

	# One caller job per (graph node, arch). glbx emits the per-arch graph; jq
	# turns it into YAML in a single pass: node index becomes a stable, GHA-safe
	# job id prefixed by arch (node-<arch>-<i>) so the two arches never collide,
	# the node's short name rides in the job name (so the Actions UI shows just
	# "libc6" or "rootfs", grouping the two arches of a package under one name)
	# while the full arch-qualified Key rides in the node-key input, and each
	# node's incoming edges become needs: on the same-arch predecessor jobs. The
	# build logic itself is in build-node.yml; the needs: edges and the if: skip
	# guard stay here because they are structural — exactly what check-graph
	# validates.
	for a in $ARCHES; do
		"$GLBX" graph --format=json --conf-dir "$CONF_DIR" --stub "$STUB" --arch "$a" 2>/dev/null \
			| jq -r --arg q "'" --arg arch "$a" --slurpfile r "$RUNNERS" '
				(.nodes | to_entries | map({(.value.key): .key}) | add) as $id
				| .edges as $edges
				| ($r[0]) as $runners
				| .nodes
				| to_entries[]
				| .key as $i
				| .value.key as $key
				| .value.shortName as $short
				| ([$edges[] | select(.to == $key) | "node-\($arch)-\($id[.from])"] | sort) as $preds
				| (["build-glbx", "check-graph", "restore-inputs-\($arch)", "plan-\($arch)"] + $preds) as $needs
				| ($runners.overrides[$key] // $runners.default[$arch]) as $runner
				| "
  node-\($arch)-\($i):
    name: \"\($short)\"
    needs: [\($needs | join(", "))]
    # Build unless this node is already present in the registry. A skipped
    # (already-built) dependency must not cascade-skip a dependent that does
    # need rebuilding, so !cancelled() && !failure() replaces the implicit
    # success() gate — which treats a skipped need as reason to skip. The skip
    # fires only on an explicit true: an empty plan output or a missing key
    # builds, so anything unexpected errs toward building.
    if: \"${{ !cancelled() && !failure() && (needs[\($q)plan-\($arch)\($q)].outputs.built == \($q)\($q) || fromJSON(needs[\($q)plan-\($arch)\($q)].outputs.built)[\($q)\($key)\($q)] != true) }}\"
    uses: ./.github/workflows/build-node.yml
    with:
      node-key: \"\($key)\"
      arch: \($arch)
      runner: \"\($runner)\"
      id-seed-override: \"${{ inputs.id-seed-override }}\""
			'
	done
} >"$OUT"

echo "wrote $OUT ($(wc -l <"$OUT") lines)"
